/**
 * @file    svpwm.c
 * @brief   SVPWM implementation for edge-aligned PWM mode (XMC4200 CCU8)
 * @version 1.0
 * @date    2026-08-19
 * @author  SVPWM Implementation Agent
 *
 * This module implements Space Vector PWM for a three-phase inverter using
 * the XMC4200 CCU8 peripheral in edge-aligned (sawtooth) PWM mode.
 */

#include "svpwm.h"
#include <math.h>

/* Constants */
#define SQRT3    1.7320508075688772f
#define INV_SQRT3 0.5773502691896258f

/**
 * @brief Determine SVPWM sector from Valpha, Vbeta using three-variable sign method
 *
 * This method determines the sector by computing three auxiliary variables
 * and extracting a 3-bit code from their signs.
 *
 * Sector determination logic:
 * - Vref1 = Vbeta
 * - Vref2 = (sqrt(3) * Valpha - Vbeta) / 2
 * - Vref3 = (-sqrt(3) * Valpha - Vbeta) / 2
 *
 * Bit extraction:
 * - A = 1 if Vref1 > 0, else 0
 * - B = 1 if Vref2 > 0, else 0
 * - C = 1 if Vref3 > 0, else 0
 *
 * 3-bit code N = 4*C + 2*B + A
 *
 * Sector lookup:
 * - N=1 -> Sector 2
 * - N=2 -> Sector 6
 * - N=3 -> Sector 1
 * - N=4 -> Sector 4
 * - N=5 -> Sector 3
 * - N=6 -> Sector 5
 *
 * @param Valpha Alpha component (float, Volts)
 * @param Vbeta  Beta component (float, Volts)
 * @return Sector number (0-6)
 */
static int determine_sector(float Valpha, float Vbeta)
{
    float Vref1 = Vbeta;
    float Vref2 = (SQRT3 * Valpha - Vbeta) * 0.5f;
    float Vref3 = (-SQRT3 * Valpha - Vbeta) * 0.5f;

    int A = (Vref1 > 0.0f) ? 1 : 0;
    int B = (Vref2 > 0.0f) ? 1 : 0;
    int C = (Vref3 > 0.0f) ? 1 : 0;

    int N = (4 << C) | (2 << B) | A;

    /* Sector lookup table based on 3-bit code */
    static const int8_t sector_table[7] = {0, 2, 6, 1, 4, 3, 5};

    /* Handle case where reference is outside hexagon (should not happen in linear range) */
    if (N < 1 || N > 6) {
        N = 1;  /* Fallback to sector 1 */
    }

    return sector_table[N];
}

/**
 * @brief Calculate SVPWM compare values for edge-aligned PWM mode
 *
 * This function calculates the PWM compare register values for each phase
 * based on the alpha-beta voltage reference.
 *
 * Sector determination uses the three-variable sign method.
 * Dwell times T1, T2, and T0 are calculated using sector-specific formulas.
 * The zero vector time T0 is distributed according to t0_split_factor=4
 * (due to CCU8 double-buffering behavior).
 *
 * T0 Distribution for Edge-Aligned Mode (t0_split_factor=4):
 * - For each sector, T0 is split into 4 parts
 * - T0/4 is added as an offset to each phase compare value
 * - This accounts for CCU8's shadow register behavior
 *
 * Compare value calculation:
 * - CMP_X = PWM_HALF_PERIOD + (timing_offset_for_phase_X)
 * - Timing offset is the cumulated dwell time for that phase plus the T0 offset
 *
 * Phase ordering by sector:
 * - Sector 1 (0-60°): U leads, V mid, W lags
 * - Sector 2 (60-120°): V leads, W mid, U lags
 * - Sector 3 (120-180°): V leads, W mid, U lags (phases shift)
 * - Sector 4 (180-240°): W leads, U mid, V lags
 * - Sector 5 (240-300°): W leads, U mid, V lags (phases shift)
 * - Sector 6 (300-360°): U leads, W mid, V lags
 *
 * @param vref Input structure containing Valpha and Vbeta
 * @param out  Output structure for compare values
 *
 * @note: The DC bus voltage is used for scaling the voltage reference
 *        to the appropriate time domain.
 */
void svpwm_calculate(const SVPWMInput_t *vref, SVPWMOutput_t *out)
{
    float Valpha = vref->Valpha;
    float Vbeta  = vref->Vbeta;

    /* Determine sector (0-6) */
    int sector = determine_sector(Valpha, Vbeta);

    /* Calculate intermediate values for dwell time computation */
    /* The factor SQRT3 * PWM_HALF_PERIOD / DC_BUS accounts for:
     * - The geometric sqrt(3) factor in the voltage space
     * - Conversion from voltage to time domain
     * - Normalization to PWM_HALF_PERIOD for CCU8 calculations
     */
    float K = SQRT3 * PWM_HALF_PERIOD / DC_BUS_VOLTAGE;

    /* Calculate intermediate dwell time components */
    /* These represent the projections of the reference vector onto the active vectors */
    float X = K * Vbeta;
    float Y = K * (SQRT3 * Valpha * 0.5f + Vbeta * 0.5f);
    float Z = K * (-SQRT3 * Valpha * 0.5f + Vbeta * 0.5f);

    float T1, T2;  /* Dwell times for active vectors */

    /* Calculate T1 and T2 based on sector */
    /* Reference vector V_ref = (Valpha, Vbeta) */
    /* Active vectors:
     * - V1: (2/3 * Vdc, 0)       -> per-unit: (2/3, 0)
     * - V2: (1/3 * Vdc, Vdc/sqrt(3)) -> per-unit: (1/3, 1/sqrt(3))
     * - V3: (-1/3 * Vdc, Vdc/sqrt(3)) -> per-unit: (-1/3, 1/sqrt(3))
     * - V4: (-2/3 * Vdc, 0)      -> per-unit: (-2/3, 0)
     * - V5: (-1/3 * Vdc, -Vdc/sqrt(3)) -> per-unit: (-1/3, -1/sqrt(3))
     * - V6: (1/3 * Vdc, -Vdc/sqrt(3)) -> per-unit: (1/3, -1/sqrt(3))
     */
    switch (sector) {
        case 1:
            /* Sector 1: Use V2 and V1 */
            T1 =  Z;  /* Time with V2 */
            T2 =  X;  /* Time with V1 */
            break;
        case 2:
            /* Sector 2: Use V2 and V3 */
            T1 =  X;
            T2 = -Z;
            break;
        case 3:
            /* Sector 3: Use V3 and V4 */
            T1 =  X;
            T2 =  Z;
            break;
        case 4:
            /* Sector 4: Use V5 and V4 */
            T1 = -Z;
            T2 = -X;
            break;
        case 5:
            /* Sector 5: Use V5 and V6 */
            T1 = -X;
            T2 =  Z;
            break;
        case 6:
            /* Sector 6: Use V6 and V1 */
            T1 = -X;
            T2 =  Y;
            break;
        default:
            /* Sector 0: Zero vector (should not normally occur) */
            T1 =  Z;
            T2 =  Y;
            break;
    }

    /* Clamp dwell times to linear modulation range */
    /* In the linear range, T1 + T2 <= PWM_PERIOD (or PWM_HALF_PERIOD for center-aligned) */
    /* If overmodulation, clamp T1 + T2 to PWM_PERIOD and adjust T0 accordingly */
    if (T1 + T2 > PWM_PERIOD) {
        /* Overmodulation: clamp to linear range */
        T1 = PWM_PERIOD * (T1 / (T1 + T2));
        T2 = PWM_PERIOD * (T2 / (T1 + T2));
        T1 = T1 / 2.0f;  /* After rescaling, halve both */
        T2 = T2 / 2.0f;
        T1 += T2;  /* Recalculate total */
    }

    /* Calculate T0 (zero vector dwell time) */
    float T0 = PWM_PERIOD - (T1 + T2);

    /*
     * T0 Distribution for CCU8 Edge-Aligned Mode
     *
     * CCU8 has double-buffered shadow registers and hardware dead-time insertion.
     * This causes T0 to be effectively split into 4 parts rather than 2.
     *
     * The compare values are calculated relative to PWM_HALF_PERIOD (500).
     *
     * For edge-aligned mode:
     * - Counter counts from 0 to PWM_PERIOD
     * - Output is HIGH when counter < CMP_X
     *
     * With t0_split_factor=4, T0 is distributed as:
     * - T0/4 at counter = 0
     * - T0/4 at counter = PWM_PERIOD (end of period)
     * - T0/2 distributed between the phase transitions
     *
     * The compare values account for this T0 distribution:
     *
     * For each phase, the compare value is:
     *   CMP_X = PWM_HALF_PERIOD + (phase_timing_offset)
     *
     * where phase_timing_offset depends on the sector.
     */

    /* t0_split_factor for CCU8 */
    const int t0_split_factor = 4;

    /* Calculate T0_base (time offset for each T0/4 segment) */
    /* T0 is split into t0_split_factor equal parts */
    float T0_base = T0 / (float)t0_split_factor;

    /* Calculate timing offsets for each phase based on sector */
    /* Ta, Tb, Tc represent the cumulative timing for phases U, V, W respectively */
    float Ta, Tb, Tc;

    /* Sector 1: U leads, V is mid, W lags */
    switch (sector) {
        case 1:
            /* U: T1 + T0_base (leading phase) */
            /* V: T2 + T0_base (mid phase) */
            /* W: T0_base (lagging phase, only gets one T0/4) */
            Ta = T1 + T0_base;
            Tb = T2 + T0_base;
            Tc = T0_base;
            break;

        case 2:
            /* V: T1 + T0_base (leading) */
            /* W: T2 + T0_base (mid) */
            /* U: T0_base (lagging) */
            Ta = T0_base;
            Tb = T1 + T0_base;
            Tc = T2 + T0_base;
            break;

        case 3:
            /* V: T1 + T2 + T0_base (leading and mid) */
            /* W: T2 + T0_base (mid) */
            /* U: T0_base (lagging) */
            Ta = T0_base;
            Tb = T1 + T2 + T0_base;
            Tc = T2 + T0_base;
            break;

        case 4:
            /* W: T1 + T0_base (leading) */
            /* U: T1 + T2 + T0_base (mid and lagging) */
            /* V: T0_base (lagging) */
            Ta = T1 + T0_base;
            Tb = T0_base;
            Tc = T1 + T2 + T0_base;
            break;

        case 5:
            /* W: T1 + T2 + T0_base (leading) */
            /* U: T2 + T0_base (mid) */
            /* V: T0_base (lagging) */
            Ta = T2 + T0_base;
            Tb = T0_base;
            Tc = T1 + T2 + T0_base;
            break;

        case 6:
            /* U: T1 + T2 + T0_base (leading) */
            /* W: T0_base + T0_base (mid and lagging, two T0/4 segments) */
            /* V: T0_base (lagging) */
            Ta = T1 + T2 + T0_base;
            Tb = T0_base;
            Tc = T1 + T0_base;
            break;

        default:
            /* Sector 0: Zero vector, equal duty on all phases */
            Ta = T1 + T2 + T0_base;
            Tb = T2 + T0_base;
            Tc = T0_base;
            break;
    }

    /* Map to compare values */
    out->cmp_u = (uint16_t)(Ta + 0.5f);  /* Round to nearest integer */
    out->cmp_v = (uint16_t)(Tb + 0.5f);
    out->cmp_w = (uint16_t)(Tc + 0.5f);

    /* Clamp compare values to valid range [0, PWM_PERIOD] */
    /* This ensures the compare values don't exceed the PWM counter range */
    if (out->cmp_u > PWM_PERIOD) {
        out->cmp_u = PWM_PERIOD;
    }
    if (out->cmp_v > PWM_PERIOD) {
        out->cmp_v = PWM_PERIOD;
    }
    if (out->cmp_w > PWM_PERIOD) {
        out->cmp_w = PWM_PERIOD;
    }
    if (out->cmp_u < 0) {
        out->cmp_u = 0;
    }
    if (out->cmp_v < 0) {
        out->cmp_v = 0;
    }
    if (out->cmp_w < 0) {
        out->cmp_w = 0;
    }
}
